	["BreachHiveAddModifierToRareSkill"] = {
		["description"] = "A skill created by Ailith that creates a zone which adds a [MonsterModifiers|Modifier] to Rare Breach Monsters which enter it.\13\
\13\
A Rare Monster can only have one Modifier added.",
		["name"] = "Dreamer's Inspiration",
	},
	["BreachHiveAdditionalRarePackSkill"] = {
		["description"] = "A skill created by Ailith that adds an additional Pack with a Rare Monster to each wave.",
		["name"] = "Otherworldly Nemesis",
	},
	["BreachHiveMonsterPotencySkill"] = {
		["description"] = "A skill created by Ailith that increases the [MonsterEffectiveness|Effectiveness] of Monsters in [ContainsBreach|Breach] Hive encounters.",
