	["GraspingVines"] = {
		["description"] = "Grasping Vines is a stacking [Debuff] that [Slow|Slows] character movement speed by 8% for each stack applied.\13\
Moving will gradually remove stacks of Grasping Vines.",
		["name"] = "Grasping Vines",
	},
	["GreatBeast"] = {
