	["IncursionMedallionIncreaseRoomTier"] = {
		["description"] = "Quipolatl's Medallion [IncursionRoomUpgrades|Upgrades] the Tier of a Room",
		["name"] = "Quipolatl's Medallion",
	},
	["IncursionMedallionMaximumCrystalCapacity"] = {
