	["Invocation"] = {
		["description"] = "Invocation Skills are [Persistent] Skills that gain [Energy] through some condition and can be used once sufficient [Energy] has been gathered to [Invoke] socketed Skills, expending the [Energy] to [Trigger] them. Invocations can [Trigger] socketed Skills multiple times if enough [Energy] is expended, unless otherwise specified.",
