	["ObeliskCleansing"] = {
		["description"] = "An Obelisk of Cleansing is an object that activates once a player gets close enough; granting a 10 second [Buff] that grants 100% [ItemRarity|Item Rarity], 50% increased [Armour], [Evasion] and [EnergyShield|Energy Shield] and makes players [Gain] 30% of Damage as extra [Lightning] Damage.",
		["name"] = "Obelisk of Cleansing",
	},
	["ObeliskCorruption"] = {
		["description"] = "An Obelisk of Corruption is an object that activates once a player gets close enough; granting a 10 second [Buff] that makes enemies killed by you explode, dealing 10% of their life as [Physical] damage.",
		["name"] = "Obelisk of Corruption",
	},
	["Offering"] = {
		["description"] = "Offering Skills target an active Skeleton [Minion] to create an Offering Spike. Offering Spikes grant various [Buff|Buffs] to you or your [Minion|Minions], and can even directly damage Enemies. Offering Skills are themselves damageable [Minion|Minions] and their [Buff|Buffs] are lost if they die.",
		["name"] = "Offering Skills",
	},
	["Oil"] = {
		["description"] = "Enemies covered in Oil have their movement speed [Slow|Slowed], are inflicted with [Exposure] and have 200% more [BuffMagnitude|Magnitude] of [Flammability] inflicted on them.\13\
\13\
[IgnitedGround|Ignited Ground] or [Detonator] Skills will [Ignite] Oil-covered enemies. This removes the Oil, but the [Exposure] will remain for the duration of that [Ignite].",
		["name"] = "Covered in Oil",
	},
	["OilGround"] = {
		["description"] = "Enemies standing in Oil Ground have their movement speed [Slow|Slowed] and are inflicted with [Exposure].\13\
\13\
[Ignite|Ignited] enemies, [IgnitedGround|Ignited Ground], or [Detonator] Skills that touch the Oil cause it to catch fire, [Ignite|Igniting] enemies instead of [Slow|Slowing] them, but still inflicting the [Exposure].",
