	},
	["Parry"] = {
		["description"] = "Parry is a Skill granted by [Buckler|Bucklers], [Targe|Targes] and dual wielded [Sword|Swords] that allows you to [Block] and retaliate against an enemy [Hit], leaving them off balance and inflicting the [ParriedDebuff|Parried Debuff].",
		["name"] = "Parry",
	},
	["Payoff"] = {
		["description"] = "Payoff Skills have powerful extra affects when [Hit|Hitting] enemies inflicted with specific [Debuff|Debuffs], often [Consume|Consuming] the [Debuff] in the process. Payoff Skills cannot inflict the [Debuff] they interact with.",
		["name"] = "Payoff Skills",
	},
	["Penetration"] = {
		["description"] = "Penetration causes the target's corresponding [Resistances|Resistance] to be treated as lower than its actual value by the specified amount when of calculating Damage taken from your [Hit|Hits]. [Resistances] can only be Penetrated down to a minimum of 0% by default.\13\
\13\
Since Penetration only affects [Hit|Hits] and applies to the target's defensive stats rather than your own offensive stats, it does not affect damage with [DamagingAilments|Ailments].",
