	["TimeRune"] = {
		["description"] = "<<ExpedRuneTime>><rgb(219,217,206)>{Time Rune}\13\
<font:'fontin'>{<italic>{<rgb(110,87,66)>{Monsters gain:}}}\13\
<rgb(135,134,253)>{Slain Monsters may respawn as a higher Rarity}",
