		["description"] = "Ruin is gained if you are hit by a Stalking Shade inside the Trial of Chaos.\13\
\13\
Fail the Trials on reaching 7 Ruin",
		["name"] = "Ruin",
	},
	["Unaffected"] = {
		["description"] = "[Debuff|Debuffs] you are Unaffected by can still be placed on you, but will not actually apply their effect.",
